package com.trawlingplus;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * The display on the boat, in its own layer above the game's health bars, hitsplats and overhead text but under the
 * interface. The route stays with the main overlay.
 */
class TrawlingPlusHelmOverlay extends Overlay
{
	private final Client client;
	private final TrawlingPlusOverlay overlay;

	TrawlingPlusHelmOverlay(Client client, TrawlingPlusPlugin plugin, TrawlingPlusOverlay overlay)
	{
		super(plugin);
		this.client = client;
		this.overlay = overlay;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.UNDER_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		// Not just while the guides are showing: the hold's display shows in either guides mode, even on a raft.
		if (client.getGameState() != GameState.LOGGED_IN || !overlay.displayWanted())
		{
			return null;
		}

		Object antialiasing = graphics.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		overlay.drawHelm(graphics);
		if (antialiasing != null)
		{
			graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, antialiasing);
		}
		return null;
	}
}

package com.trawlingplus;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.geom.Area;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Point;
import net.runelite.api.SpritePixels;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import net.runelite.client.ui.overlay.worldmap.WorldMapOverlay;

/**
 * Draws every shown shoal route on the world map, straight after the map itself, so RuneLite's and other plugins' map
 * markers sit on top.
 */
class TrawlingPlusMapOverlay extends Overlay
{
	private static final int THICKNESS = 2;
	private static final int ARROW = 6;
	// A shoal's mark: its dot while still, this many pixels across, or its arrow while moving; the game's stop bar
	// under it at a stop, this wide; and the arrow at the map's edge pointing to the last trawled one off the map.
	private static final int SHOAL_DOT = 8;
	private static final int HEADING_ARROW = 12;
	// A stop's outline, across.
	private static final int STOP = 7;
	// How close the mouse must be to a route's line to show its tooltip, and to a skull or shoal icon to leave the
	// tooltip to it, in pixels.
	private static final double ROUTE_HOVER = 5;
	private static final double ICON_HOVER = 9;
	private static final int EDGE_ARROW = 17;
	// How far the edge arrow's middle sits inside the map's edge.
	private static final int EDGE_ARROW_INSET = 12;
	private static final int BAR_WIDTH = 26;
	// How many pixels at the bar picture's right end are its end, taken as they are.
	private static final int BAR_END = 2;

	// A skull and crossbones, put on the world map as RuneLite world map points (for the game's style of tooltip) where
	// sea creatures that attack boats spawn close enough to threaten a route.
	static final BufferedImage DANGER_ICON = dangerIcon();

	// The tile the map is asked to place, which every other point is placed from.
	private static final int PLACED_TILE = 3200;

	/**
	 * A small skull and crossbones, drawn once. White with a dark edge, so it reads on sea and land alike.
	 */
	private static BufferedImage dangerIcon()
	{
		BufferedImage icon = new BufferedImage(13, 13, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = icon.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		// The crossed bones, poking out from behind the skull at each corner.
		g.setStroke(new BasicStroke(3f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(Color.BLACK);
		g.drawLine(2, 2, 10, 10);
		g.drawLine(10, 2, 2, 10);
		g.setStroke(new BasicStroke(1.4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(Color.WHITE);
		g.drawLine(2, 2, 10, 10);
		g.drawLine(10, 2, 2, 10);

		// The skull: a round head over a narrower jaw, with two dark eyes.
		g.setColor(Color.BLACK);
		g.fillOval(2, 1, 9, 8);
		g.fillRect(4, 6, 5, 4);
		g.setColor(Color.WHITE);
		g.fillOval(3, 2, 7, 6);
		g.fillRect(5, 6, 3, 3);
		g.setColor(Color.BLACK);
		g.fillRect(4, 4, 2, 2);
		g.fillRect(7, 4, 2, 2);
		g.dispose();
		return icon;
	}

	private final Client client;
	private final TrawlingPlusPlugin plugin;
	private final TrawlingPlusConfig config;
	private final WorldMapOverlay worldMapOverlay;
	private final SpriteManager spriteManager;
	private final TooltipManager tooltipManager;
	private final MapRoutes.MapView mapView = new MapRoutes.MapView();
	private final MapRoutes.Clickable edgeArrow = new MapRoutes.Clickable();
	private final MapRoutes.Clickable trawledMark = new MapRoutes.Clickable();
	// The stop bar's two pictures as a skin or resource pack replaces them, and what each was read from.
	private final SpritePixels[] barSources = new SpritePixels[2];
	private final BufferedImage[] barPictures = new BufferedImage[2];

	@Inject
	TrawlingPlusMapOverlay(Client client, TrawlingPlusPlugin plugin, TrawlingPlusConfig config,
		WorldMapOverlay worldMapOverlay, SpriteManager spriteManager, TooltipManager tooltipManager)
	{
		super(plugin);
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.worldMapOverlay = worldMapOverlay;
		this.spriteManager = spriteManager;
		this.tooltipManager = tooltipManager;
		setPosition(OverlayPosition.DYNAMIC);
		// Right after the world map and at the lowest priority, so markers that RuneLite and other plugins draw
		// after the same interface at a higher priority sit on top of the routes rather than under them.
		setLayer(OverlayLayer.MANUAL);
		drawAfterInterface(InterfaceID.WORLDMAP);
		setPriority(PRIORITY_LOW);
	}

	/**
	 * The part of the map showing the world, less its overview and map list panels, as RuneLite's own markers leave
	 * out. A plain rectangle while neither is open, which keeps Java2D on its quick path.
	 */
	private Shape mapArea(Rectangle within)
	{
		Area area = null;
		for (int panel : new int[]{InterfaceID.Worldmap.OVERVIEW_CONTAINER, InterfaceID.Worldmap.MAPLIST_BOX_GRAPHIC0})
		{
			Widget widget = client.getWidget(panel);
			if (widget != null && !widget.isHidden())
			{
				if (area == null)
				{
					area = new Area(within);
				}
				area.subtract(new Area(widget.getBounds()));
			}
		}
		return area != null ? area : within;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		edgeArrow.clear();
		trawledMark.clear();
		TrawlingPlusConfig.ShowOnMaps where = config.showOnMaps();
		if (client.getGameState() != GameState.LOGGED_IN
			|| where == TrawlingPlusConfig.ShowOnMaps.OFF
			|| where == TrawlingPlusConfig.ShowOnMaps.MINIMAP)
		{
			return null;
		}

		Widget map = client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER);
		if (map == null || map.isHidden())
		{
			return null;
		}

		// Deliberately not behind the Show guides setting: a map is for working out where to go, which
		// is something done before boarding a boat and fitting a net to it.
		Rectangle within = map.getBounds();

		// One tile placed by the map, and its zoom in pixels a tile. The map only scales and shifts the world, north
		// up, so every other point is placed from these with a few sums.
		Point placed = worldMapOverlay.mapWorldPointToGraphicsPoint(new WorldPoint(PLACED_TILE, PLACED_TILE, 0));
		double zoom = client.getWorldMap().getWorldMapZoom();
		if (placed == null || zoom <= 0)
		{
			return null;
		}
		mapView.place(PLACED_TILE, PLACED_TILE, placed.getX(), placed.getY(), zoom, 0, 0, -zoom);
		mapView.edges(within, false);

		// Which stretch of the world the map is showing, worked out by running the placing backwards from the corners
		// of the map, with a tile of slack. A run of route outside it is passed over without placing any of it.
		double fromX = PLACED_TILE + (within.x - placed.getX()) / zoom - 1;
		double toX = PLACED_TILE + (within.x + within.width - placed.getX()) / zoom + 1;
		double fromY = PLACED_TILE - (within.y + within.height - placed.getY()) / zoom - 1;
		double toY = PLACED_TILE - (within.y - placed.getY()) / zoom + 1;

		Shape clip = graphics.getClip();
		graphics.clip(mapArea(within));

		boolean danger = config.showDanger().onMaps();
		Color lineDanger = danger ? MapRoutes.withAlphaOf(config.dangerColour(), config.routeColour()) : null;
		Color arrowDanger = danger ? MapRoutes.withAlphaOf(config.dangerColour(), config.directionArrowColour()) : null;
		MapRoutes.MapTimer timer = MapRoutes.mapTimer;
		long lineNanos = 0;
		long arrowNanos = 0;
		for (ShoalRoute route : plugin.getShownRoutes())
		{
			// Whether any of the route could be on screen, from the box it fits inside. The map is panned and zoomed
			// freely, so most of the time most routes are nowhere near it.
			if (!route.overlaps(fromX, fromY, toX, toY))
			{
				continue;
			}

			// The arrows first, so the line runs over them.
			long started = timer == null ? 0 : System.nanoTime();
			MapRoutes.arrows(graphics, config, route, mapView, ARROW, fromX, fromY, toX, toY, arrowDanger);
			long drawn = timer == null ? 0 : System.nanoTime();
			MapRoutes.route(graphics, config, route, mapView, THICKNESS, fromX, fromY, toX, toY, lineDanger);
			if (timer != null)
			{
				arrowNanos += drawn - started;
				lineNanos += System.nanoTime() - drawn;
			}
		}
		if (timer != null)
		{
			timer.mapTook(MapRoutes.MapTimer.WORLD_LINES, lineNanos);
			timer.mapTook(MapRoutes.MapTimer.WORLD_ARROWS, arrowNanos);
		}

		if (config.showStops())
		{
			long started = timer == null ? 0 : System.nanoTime();
			drawStops(graphics, fromX, fromY, toX, toY);
			if (timer != null)
			{
				timer.mapTook(MapRoutes.MapTimer.WORLD_STOPS, System.nanoTime() - started);
			}
		}
		drawShoals(graphics, mapView, within);
		Shape area = graphics.getClip();
		graphics.setClip(clip);
		if (config.showRouteTooltips())
		{
			routeTip(area, placed, zoom);
		}
		return null;
	}

	/**
	 * The tooltip of the route line under the mouse, if any: its fish and name, then its stops and how long a lap and
	 * a stop take. Not over the shoal marks, the edge arrow, or a skull or shoal icon with a tooltip of its own.
	 */
	private void routeTip(Shape area, Point placed, double zoom)
	{
		Point mouse = client.getMouseCanvasPosition();
		if (client.isMenuOpen() || area == null || !area.contains(mouse.getX(), mouse.getY())
			|| trawledMark.at(mouse.getX(), mouse.getY()) != null || edgeArrow.at(mouse.getX(), mouse.getY()) != null
			|| plugin.tooltipPointNear(mapView, mouse.getX(), mouse.getY(), ICON_HOVER))
		{
			return;
		}

		// The tiles under the mouse, with the hover reach round them.
		double tileX = PLACED_TILE + (mouse.getX() - placed.getX()) / zoom;
		double tileY = PLACED_TILE - (mouse.getY() - placed.getY()) / zoom;
		double reach = ROUTE_HOVER / zoom + 1;
		ShoalRoute nearest = null;
		double nearestPixels = ROUTE_HOVER;
		for (ShoalRoute route : plugin.getShownRoutes())
		{
			if (!route.overlaps(tileX - reach, tileY - reach, tileX + reach, tileY + reach))
			{
				continue;
			}
			double pixels = MapRoutes.pixelsFrom(route, mapView, mouse.getX(), mouse.getY(), tileX - reach,
				tileY - reach, tileX + reach, tileY + reach);
			if (pixels <= nearestPixels)
			{
				nearest = route;
				nearestPixels = pixels;
			}
		}
		if (nearest == null)
		{
			return;
		}

		String tip = nearest.getSpecies() + " at " + nearest.getName() + "</br>" + nearest.stopCount() + " stops";
		if (nearest.timed())
		{
			tip += ", " + clock(nearest.lapTicks()) + " a lap, " + clock(nearest.stopTicks()) + " at each stop";
		}
		tooltipManager.add(new Tooltip(tip));
	}

	/**
	 * Game ticks as minutes and seconds, such as 1:29.
	 */
	private static String clock(int ticks)
	{
		int seconds = (int) Math.round(ticks * 0.6);
		return seconds / 60 + ":" + String.format("%02d", seconds % 60);
	}

	/**
	 * Every shown route's stops in the given box of tiles, over the lines and under the shoals, the last trawled
	 * route's next stop taken from where its shoal likely is while it's out of view.
	 */
	private void drawStops(Graphics2D graphics, double fromX, double fromY, double toX, double toY)
	{
		ShoalRoute trawled = config.showPredictedOnMap() ? plugin.getTrawledRoute() : null;
		for (ShoalRoute route : plugin.getShownRoutes())
		{
			if (!route.overlaps(fromX, fromY, toX, toY))
			{
				continue;
			}
			long now = System.currentTimeMillis();
			double likely = route == trawled ? plugin.getForecast().distance(route, now) : -1;
			boolean likelyStopped = likely >= 0 && plugin.getForecast().stopLeft(route, now) >= 0;
			MapRoutes.stops(graphics, config, route, mapView, STOP, fromX, fromY, toX, toY,
				MapRoutes.stopStates(plugin, client, route, likely, likelyStopped));
		}
	}

	/**
	 * Every shoal as one mark on its route's line: one in view where the game has it along its route, and the last one
	 * trawled, while out of view, where it likely is.
	 */
	private void drawShoals(Graphics2D graphics, MapRoutes.MapView onto, Rectangle within)
	{
		Color colour = config.shoalHeadingArrowColour();
		int tick = client.getTickCount();
		ShoalRoute trawled = plugin.getTrawledRoute();
		// By what the game is drawing this frame, so the last trawled shoal's dot hands over the moment it leaves or
		// comes into view, with neither a gap nor two at once.
		boolean trawledInView = false;
		// Where the last trawled shoal is, in view or likely, while it's off the part of the map showing.
		double[] offMap = null;
		// Only a shoal the client is drawing in the world is taken from the game. Shoals are dropped as they despawn
		// anyway, so this is belt and braces.
		for (Shoal shoal : plugin.getShoals())
		{
			if (!plugin.isShown(shoal) || !shoal.rendered(client))
			{
				continue;
			}
			boolean isTrawled = trawled != null && shoal.getRoute() == trawled;
			trawledInView |= isTrawled;
			double[] at = MapRoutes.alongRoute(shoal, client);
			Point placed = at == null ? null : onto.at(at[0], at[1]);
			if (placed == null)
			{
				offMap = isTrawled && at != null ? at : offMap;
				continue;
			}

			// The stop bar over it, read off the game; or else, as for a shoal out of view, the way its route runs
			// there.
			double left = shoal.stopBarNow(tick);
			boolean heading = left < 0 && at.length > 2;
			drawMark(graphics, placed, colour, left, heading ? onto.stepX(at[2], at[3]) : 0,
				heading ? onto.stepY(at[2], at[3]) : 0);
			if (isTrawled)
			{
				noteTrawledMark(graphics, trawled, placed);
			}
		}

		// The last trawled shoal, while out of view, where it likely is.
		if (config.showPredictedOnMap() && trawled != null && !trawledInView && plugin.getShownRoutes().contains(trawled))
		{
			ShoalForecast forecast = plugin.getForecast();
			long now = System.currentTimeMillis();
			double along = forecast.distance(trawled, now);
			double[] at = along < 0 ? null : trawled.pointAt(along);
			Point placed = at == null ? null : onto.at(at[0], at[1]);
			if (placed != null)
			{
				// At a stop, how much of it is likely left; otherwise the way it's heading, along the route.
				double left = forecast.stopLeft(trawled, now);
				drawMark(graphics, placed, colour, left, onto.stepX(at[2], at[3]), onto.stepY(at[2], at[3]));
				noteTrawledMark(graphics, trawled, placed);
			}
			else
			{
				offMap = at;
			}
		}

		if (offMap != null && config.predictedMapEdgeArrow() && plugin.getAboardBoat() != null
			&& !plugin.isEdgeArrowHidden())
		{
			drawEdgeArrow(graphics, within, trawled, onto.x(offMap[0], offMap[1]), onto.y(offMap[0], offMap[1]), colour);
		}
	}

	/**
	 * An arrow just inside the map's edge, on the line from the map's middle to a point off it, pointing at it.
	 */
	private void drawEdgeArrow(Graphics2D graphics, Rectangle within, ShoalRoute route, double x, double y,
		Color colour)
	{
		double towardX = x - within.getCenterX();
		double towardY = y - within.getCenterY();
		double roomX = within.width / 2.0 - EDGE_ARROW_INSET;
		double roomY = within.height / 2.0 - EDGE_ARROW_INSET;
		double reach = Math.min(Math.abs(towardX) < 1e-6 ? Double.MAX_VALUE : roomX / Math.abs(towardX),
			Math.abs(towardY) < 1e-6 ? Double.MAX_VALUE : roomY / Math.abs(towardY));
		if (roomX <= 0 || roomY <= 0 || reach == Double.MAX_VALUE)
		{
			return;
		}
		double arrowX = within.getCenterX() + towardX * reach;
		double arrowY = within.getCenterY() + towardY * reach;
		MapRoutes.pointer(graphics, arrowX, arrowY, colour, EDGE_ARROW, towardX, towardY);
		// Only one showing can be right-clicked, not one under the map's panels.
		Shape showing = graphics.getClip();
		if (showing == null || showing.contains(arrowX, arrowY))
		{
			edgeArrow.drawn(route, arrowX, arrowY, EDGE_ARROW);
		}
	}

	/**
	 * Keeps where the last trawled shoal's mark was drawn, for its right-click menu, unless under the map's panels.
	 */
	private void noteTrawledMark(Graphics2D graphics, ShoalRoute route, Point placed)
	{
		Shape showing = graphics.getClip();
		if (showing == null || showing.contains(placed.getX(), placed.getY()))
		{
			trawledMark.drawn(route, placed.getX(), placed.getY(), Math.max(SHOAL_DOT, HEADING_ARROW));
		}
	}

	/**
	 * The route of the last trawled shoal's mark under a point on the canvas, or null. Client thread only.
	 */
	ShoalRoute trawledMarkAt(int x, int y)
	{
		return trawledMark.at(x, y);
	}

	/**
	 * The route of the edge arrow under a point on the canvas, or null. Client thread only.
	 */
	ShoalRoute edgeArrowAt(int x, int y)
	{
		return edgeArrow.at(x, y);
	}

	/**
	 * A shoal's mark: while moving, an arrow pointing along a step on screen; else its dot, and at a stop the game's
	 * stop bar under it with this much left (-1 for none).
	 */
	private void drawMark(Graphics2D graphics, Point at, Color colour, double left, double towardX, double towardY)
	{
		boolean stopped = left >= 0;
		MapRoutes.mark(graphics, at.getX(), at.getY(), colour, SHOAL_DOT, HEADING_ARROW, stopped ? 0 : towardX,
			stopped ? 0 : towardY);
		if (stopped)
		{
			drawStopBar(graphics, at.getX(), at.getY() + SHOAL_DOT / 2 + 4, left);
		}
	}

	/**
	 * The stop bar as the helm display shows it, a skin's or resource pack's if one replaces it, centred under a point
	 * and filled to a share. Never resized: the picture's left part, then its own right end.
	 */
	private void drawStopBar(Graphics2D graphics, int x, int top, double full)
	{
		BufferedImage front = barPicture(0, SpriteID.HeadbarIce90.FRONT);
		BufferedImage back = barPicture(1, SpriteID.HeadbarIce90.BACK);
		if (front == null || back == null)
		{
			return;
		}
		int wide = Math.min(BAR_WIDTH, Math.min(front.getWidth(), back.getWidth()));
		int high = Math.min(front.getHeight(), back.getHeight());
		int left = x - wide / 2;
		int filled = (int) Math.round(full * wide);
		drawBarPart(graphics, front, left, top, 0, filled, wide, high);
		drawBarPart(graphics, back, left, top, filled, wide, wide, high);
	}

	/**
	 * Columns from one up to another of a bar this wide, from one of its pictures, pixel for pixel: all but the last
	 * few from the picture's left part, and those from its right end.
	 */
	private static void drawBarPart(Graphics2D graphics, BufferedImage picture, int left, int top, int from, int to,
		int wide, int high)
	{
		int split = wide - BAR_END;
		int shift = picture.getWidth() - wide;
		if (from < split)
		{
			int end = Math.min(to, split);
			graphics.drawImage(picture, left + from, top, left + end, top + high, from, 0, end, high, null);
		}
		if (to > split)
		{
			int start = Math.max(from, split);
			graphics.drawImage(picture, left + start, top, left + to, top + high, start + shift, 0, to + shift, high,
				null);
		}
	}

	/**
	 * One of the stop bar's two pictures: the one a skin or resource pack has put in the client if there is one, since
	 * the sprite manager's own lookup skips them, read again only when it changes; the game's own otherwise.
	 */
	private BufferedImage barPicture(int which, int id)
	{
		SpritePixels replaced = client.getSpriteOverrides().get(id);
		if (replaced == null)
		{
			barSources[which] = null;
			barPictures[which] = null;
			return spriteManager.getSprite(id, 0);
		}
		if (replaced != barSources[which])
		{
			barSources[which] = replaced;
			barPictures[which] = replaced.toBufferedImage();
		}
		return barPictures[which];
	}
}

package com.trawlingplus;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.SpritePixels;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws the nearest shoal route on the minimap, with sparse direction arrows as on the world map.
 */
class TrawlingPlusMinimapOverlay extends Overlay
{
	// The minimap sits in a different place in each of the three screen layouts.
	private static final int[] MINIMAPS = {
		InterfaceID.Toplevel.MINIMAP,
		InterfaceID.ToplevelOsrsStretch.MINIMAP,
		InterfaceID.ToplevelPreEoc.MINIMAP
	};

	// The game's pictures of which pixels of the minimap show the map, one per size of minimap; and how far a
	// picture's size may be from the minimap's to be taken as its own, in pixels.
	private static final int[] MASKS = {SpriteID.RESIZE_MAP_MASK, SpriteID.FIXED_MAP_MASK};
	private static final int MASK_SLACK = 4;
	// How many game ticks after a setting or plugin change to look for a resource pack's new pictures, as a pack
	// puts them in a little after its setting changes.
	private static final int PACK_CHECK_TICKS = 10;

	private static final int THICKNESS = 1;
	private static final int ARROW = 6;
	// A shoal's mark: its dot while still, this many pixels across, or its arrow while moving; and the arrow at the
	// minimap's edge pointing to the last trawled one off it.
	private static final int SHOAL_DOT = 6;
	private static final int HEADING_ARROW = 9;
	// A stop's outline, across.
	private static final int STOP = 5;
	private static final int EDGE_ARROW = 11;
	// How far the edge arrow's middle sits inside the minimap's edge.
	private static final int EDGE_ARROW_INSET = 8;

	// How far either side of the boat the minimap's placing is measured from, in tiles, so whole-pixel rounding barely
	// matters; and how far from the player the minimap is asked to place a point, in local units.
	private static final int SCALE_TILES = 64;
	private static final int REACH = 128 * Perspective.LOCAL_TILE_SIZE;
	// How much slack to leave around what the minimap can show, in tiles: it's centred on the player rather than on
	// the boat, and a boat is ten tiles long.
	private static final double EDGE_SLACK = 8;

	private final Client client;
	private final TrawlingPlusPlugin plugin;
	private final TrawlingPlusConfig config;
	private final SpriteManager spriteManager;
	private final MapRoutes.MapView mapView = new MapRoutes.MapView();

	// The minimap's mask as which pixels show the map, and the minimap size it was picked for.
	private boolean[] mask;
	private int maskWidth;
	private int maskHeight;
	private int maskForWidth = -1;
	private int maskForHeight = -1;
	// The pictures the mask was made from, by sprite id, and the resource pack picture each had then (null for the
	// game's own), so a pack change makes it again.
	private final Map<Integer, SpritePixels> maskSources = new HashMap<>();
	// The game tick to stop looking for a resource pack's new pictures on.
	private int packCheckUntil = -1;

	@Inject
	TrawlingPlusMinimapOverlay(Client client, TrawlingPlusPlugin plugin, TrawlingPlusConfig config,
		SpriteManager spriteManager)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.spriteManager = spriteManager;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		// Behind Show guides, and so behind being on a boat at all, unlike the world map: the minimap is
		// for steering by, which is done from a boat.
		TrawlingPlusConfig.ShowOnMaps where = config.showOnMaps();
		if (client.getGameState() != GameState.LOGGED_IN
			|| !plugin.showGuides()
			|| where == TrawlingPlusConfig.ShowOnMaps.OFF
			|| where == TrawlingPlusConfig.ShowOnMaps.WORLD_MAP)
		{
			return null;
		}

		WorldView view = client.getTopLevelWorldView();
		Widget minimap = minimap();
		if (view == null || minimap == null)
		{
			return null;
		}

		// Lines are cut where the game's mask of the minimap ends (a circle without one) by hand, as a clip that isn't
		// a rectangle takes Java2D off its quick path.
		Rectangle bounds = minimap.getBounds();
		double radius = Math.max(bounds.width, bounds.height) / 2.0;

		// The route the boat is nearest, as on the water, drawn whether or not its shoal is in view so it can be
		// steered back to.
		ShoalRoute route = plugin.getNearestRoute();
		double[] boat = plugin.getBoatPlace();

		// Where tiles land, from two points the game places either side of the boat. The minimap turns and scales the
		// world evenly, so a step north is a step east turned a quarter.
		double middleX = boat == null ? view.getBaseX() + view.getSizeX() / 2.0 : boat[0];
		double middleY = boat == null ? view.getBaseY() + view.getSizeY() / 2.0 : boat[1];
		Point east = onMinimap(view, middleX + SCALE_TILES, middleY);
		Point west = onMinimap(view, middleX - SCALE_TILES, middleY);
		if (east == null || west == null)
		{
			return null;
		}
		double eastX = (east.getX() - west.getX()) / (2.0 * SCALE_TILES);
		double eastY = (east.getY() - west.getY()) / (2.0 * SCALE_TILES);
		mapView.place(middleX, middleY, (east.getX() + west.getX()) / 2.0, (east.getY() + west.getY()) / 2.0,
			eastX, eastY, eastY, -eastX);
		mapView.edges(bounds, true);
		shapeByMask(minimap, bounds);
		double pixelsPerTile = mapView.pixelsPerTile();
		if (pixelsPerTile <= 0)
		{
			return null;
		}

		Shape clip = graphics.getClip();
		graphics.clip(bounds);

		// Only the stretch of route the minimap could show, a couple of dozen tiles of the hundred loaded; the whole
		// scene with no boat to centre on.
		double reach = radius / pixelsPerTile + EDGE_SLACK;
		double fromX = boat == null ? view.getBaseX() : boat[0] - reach;
		double fromY = boat == null ? view.getBaseY() : boat[1] - reach;
		double toX = boat == null ? view.getBaseX() + view.getSizeX() : boat[0] + reach;
		double toY = boat == null ? view.getBaseY() + view.getSizeY() : boat[1] + reach;

		if (route != null && route.overlaps(fromX, fromY, toX, toY))
		{
			MapRoutes.MapTimer timer = MapRoutes.mapTimer;
			long started = timer == null ? 0 : System.nanoTime();
			boolean danger = config.showDanger().onMaps();
			// The arrows first, so the line runs over them.
			MapRoutes.arrows(graphics, config, route, mapView, ARROW, fromX, fromY, toX, toY,
				danger ? MapRoutes.withAlphaOf(config.dangerColour(), config.directionArrowColour()) : null);
			MapRoutes.route(graphics, config, route, mapView, THICKNESS, fromX, fromY, toX, toY,
				danger ? MapRoutes.withAlphaOf(config.dangerColour(), config.routeColour()) : null);
			long drawn = timer == null ? 0 : System.nanoTime();
			if (config.showStops())
			{
				MapRoutes.stops(graphics, config, route, mapView, STOP, fromX, fromY, toX, toY,
					MapRoutes.stopStates(plugin, client, route, -1, false));
			}
			if (timer != null)
			{
				timer.mapTook(MapRoutes.MapTimer.MINIMAP, drawn - started);
				if (config.showStops())
				{
					timer.mapTook(MapRoutes.MapTimer.MINIMAP_STOPS, System.nanoTime() - drawn);
				}
			}
		}

		// Only a shoal the client is drawing in the world may be marked on the map.
		ShoalRoute trawled = plugin.getTrawledRoute();
		double[] trawledAt = null;
		for (Shoal shoal : plugin.getShoals())
		{
			if (plugin.isShown(shoal) && shoal.rendered(client))
			{
				MapRoutes.shoal(graphics, config, client, shoal, mapView, SHOAL_DOT, HEADING_ARROW);
				if (trawled != null && shoal.getRoute() == trawled)
				{
					trawledAt = MapRoutes.alongRoute(shoal, client);
				}
			}
		}

		drawEdgeArrow(graphics, bounds, trawled, trawledAt);

		graphics.setClip(clip);
		return null;
	}

	/**
	 * While aboard, an arrow just inside the minimap's edge pointing to the last trawled shoal while it's off
	 * the minimap: where the game has it if in view, or else where it likely is.
	 */
	private void drawEdgeArrow(Graphics2D graphics, Rectangle bounds, ShoalRoute trawled, double[] at)
	{
		if (trawled == null || !config.predictedMinimapEdgeArrow() || plugin.getAboardBoat() == null
			|| plugin.isEdgeArrowHidden() || !plugin.getShownRoutes().contains(trawled))
		{
			return;
		}
		if (at == null)
		{
			double along = plugin.getForecast().distance(trawled, System.currentTimeMillis());
			at = along < 0 ? null : trawled.pointAt(along);
		}
		if (at == null)
		{
			return;
		}
		double x = mapView.x(at[0], at[1]);
		double y = mapView.y(at[0], at[1]);
		if (mapView.contains(x, y))
		{
			return;
		}
		double towardX = x - bounds.getCenterX();
		double towardY = y - bounds.getCenterY();
		double away = Math.sqrt(towardX * towardX + towardY * towardY);
		if (away < 1e-6)
		{
			return;
		}
		double room = mapView.edgeFromMiddle(towardX / away, towardY / away) - EDGE_ARROW_INSET;
		if (room <= 0)
		{
			return;
		}
		double arrowX = bounds.getCenterX() + towardX / away * room;
		double arrowY = bounds.getCenterY() + towardY / away * room;
		MapRoutes.pointer(graphics, arrowX, arrowY, config.shoalHeadingArrowColour(), EDGE_ARROW, towardX, towardY);
	}

	/**
	 * Shapes the minimap by the game's mask the size of it, less what its frame covers, made again only when its size
	 * or a resource pack changes; left round if no mask fits.
	 */
	private void shapeByMask(Widget minimap, Rectangle bounds)
	{
		if (bounds.width != maskForWidth || bounds.height != maskForHeight || packChanged())
		{
			mask = null;
			maskSources.clear();
			BufferedImage best = null;
			int bestOff = MASK_SLACK + 1;
			boolean allLoaded = true;
			for (int id : MASKS)
			{
				SpritePixels replaced = client.getSpriteOverrides().get(id);
				maskSources.put(id, replaced);
				BufferedImage image = replaced != null ? replaced.toBufferedImage() : spriteManager.getSprite(id, 0);
				if (image == null)
				{
					allLoaded = false;
					continue;
				}
				int off = Math.max(Math.abs(image.getWidth() - bounds.width),
					Math.abs(image.getHeight() - bounds.height));
				if (off < bestOff)
				{
					best = image;
					bestOff = off;
				}
			}
			if (best != null)
			{
				maskWidth = best.getWidth();
				maskHeight = best.getHeight();
				int[] pixels = best.getRGB(0, 0, maskWidth, maskHeight, null, 0, maskWidth);
				// The map shows where the mask is as see-through as at its middle.
				boolean clearShows = pixels[maskHeight / 2 * maskWidth + maskWidth / 2] >>> 24 == 0;
				mask = new boolean[pixels.length];
				for (int i = 0; i < pixels.length; i++)
				{
					mask[i] = (pixels[i] >>> 24 == 0) == clearShows;
				}
				coverByFrame(minimap, bounds);
			}
			if (best != null || allLoaded)
			{
				maskForWidth = bounds.width;
				maskForHeight = bounds.height;
			}
		}
		if (mask != null)
		{
			mapView.shape(mask, maskWidth, maskHeight);
		}
	}

	/**
	 * Looks for a resource pack's new pictures over the next few game ticks. Client thread only.
	 */
	void packMayChange()
	{
		packCheckUntil = client.getTickCount() + PACK_CHECK_TICKS;
	}

	/**
	 * Whether a resource pack has changed any picture the mask was made from, checked only for a few game ticks after
	 * {@link #packMayChange}.
	 */
	private boolean packChanged()
	{
		if (client.getTickCount() >= packCheckUntil)
		{
			return false;
		}
		Map<Integer, SpritePixels> replaced = client.getSpriteOverrides();
		for (Map.Entry<Integer, SpritePixels> source : maskSources.entrySet())
		{
			if (replaced.get(source.getKey()) != source.getValue())
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Takes out of the mask every pixel the pictures drawn after the minimap, such as its frame, draw over: the
	 * mask is where the map is drawn, and in some layouts the frame laps over it.
	 */
	private void coverByFrame(Widget minimap, Rectangle bounds)
	{
		Widget parent = minimap.getParent();
		Widget[] siblings = parent == null ? null : parent.getStaticChildren();
		if (siblings == null)
		{
			return;
		}
		int maskX = bounds.x + (bounds.width - maskWidth) / 2;
		int maskY = bounds.y + (bounds.height - maskHeight) / 2;
		boolean after = false;
		for (Widget sibling : siblings)
		{
			if (sibling == minimap)
			{
				after = true;
			}
			else if (after && sibling != null && !sibling.isHidden() && sibling.getSpriteId() >= 0
				&& !sibling.getSpriteTiling() && sibling.getBounds().intersects(bounds))
			{
				cover(sibling, maskX, maskY);
			}
		}
	}

	/**
	 * Takes out of the mask every pixel a picture widget draws over, its resource pack picture if it has one.
	 */
	private void cover(Widget widget, int maskX, int maskY)
	{
		SpritePixels picture = client.getSpriteOverrides().get(widget.getSpriteId());
		maskSources.put(widget.getSpriteId(), picture);
		if (picture == null)
		{
			SpritePixels[] sprites = client.getSprites(client.getIndexSprites(), widget.getSpriteId(), 0);
			picture = sprites == null || sprites.length == 0 ? null : sprites[0];
		}
		if (picture == null)
		{
			return;
		}
		Rectangle at = widget.getBounds();
		int[] pixels = picture.getPixels();
		int width = picture.getWidth();
		int height = picture.getHeight();
		// From a mask pixel to the same spot in the picture.
		int shiftX = maskX - at.x - picture.getOffsetX();
		int shiftY = maskY - at.y - picture.getOffsetY();
		for (int y = 0; y < maskHeight; y++)
		{
			int pictureY = y + shiftY;
			if (pictureY < 0 || pictureY >= height)
			{
				continue;
			}
			for (int x = 0; x < maskWidth; x++)
			{
				int pictureX = x + shiftX;
				if (pictureX >= 0 && pictureX < width && pixels[pictureY * width + pictureX] != 0)
				{
					mask[y * maskWidth + x] = false;
				}
			}
		}
	}

	/**
	 * World tile coordinates as a point on the minimap, placed by the game, or null when it has no minimap up.
	 */
	private Point onMinimap(WorldView view, double x, double y)
	{
		int localX = (int) Math.round((x - view.getBaseX()) * Perspective.LOCAL_TILE_SIZE)
			+ Perspective.LOCAL_HALF_TILE_SIZE;
		int localY = (int) Math.round((y - view.getBaseY()) * Perspective.LOCAL_TILE_SIZE)
			+ Perspective.LOCAL_HALF_TILE_SIZE;
		return Perspective.localToMinimap(client, new LocalPoint(localX, localY, view), REACH);
	}

	/**
	 * Whichever screen layout is up, and its minimap, or null if none of them is.
	 */
	private Widget minimap()
	{
		for (int id : MINIMAPS)
		{
			Widget found = client.getWidget(id);
			if (found != null && !found.isHidden())
			{
				return found;
			}
		}
		return null;
	}
}

package com.trawlingplus;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Marks up the facilities tab of the sailing side panel: how deep each trawling net is set, and which
 * button moves it towards the depth of the nearest shoal.
 */
class TrawlingPlusNetOverlay extends Overlay
{
	// A row is a trawling net if its picture is one of these four: raised, then each of the three fishing depths. Only
	// the picture marks a net; the frames and arrows beside it are shared with other rows.
	private static final int NET_PICTURE_RAISED = SpriteID.IconSailingFacilities24x24._12;
	private static final int NET_PICTURE_DEEPEST = SpriteID.IconSailingFacilities24x24._15;

	private static final String LOWER = "Lower net";
	private static final String RAISE = "Raise net";

	// The letter for each of the four net pictures, in the same order: raised, then the three fishing depths.
	private static final String[] LETTERS = {"R", "S", "M", "D"};
	private static final BasicStroke TWO_PIXELS = new BasicStroke(2);
	private static final Color RAISED_COLOUR = Color.WHITE;

	private static final Color HIGHLIGHT = new Color(255, 200, 0);
	private static final Color PILL = new Color(0, 0, 0, 170);
	static final Color TICK = new Color(0, 220, 80);
	private static final int PILL_PADDING = 3;

	// The tick is drawn by hand, so its size is known rather than measured.
	static final int TICK_WIDTH = 9;

	// A button counts as being on a row if their middles are within this many pixels.
	private static final int SAME_ROW = 16;

	// Pictures of facilities sit in a column down the left of the panel; the buttons start well right
	// of it. Without this the marks latch onto button frames and arrows as well.
	private static final int PICTURE_COLUMN = 40;

	// The last depth and place each net was seen with, by its position among the rows, so the marks don't flicker off
	// while its picture changes as it's raised or lowered.
	private final Map<Integer, NetRow> lastSeen = new HashMap<>();

	// The last button highlighted on each net, by the same position, and when it was found: held up to a game tick, as
	// a button briefly loses its action between steps of raising or lowering.
	private final Map<Integer, SeenButton> lastButtons = new HashMap<>();
	private static final long BUTTON_GRACE_MILLIS = 600;
	// How long a net's depth is drawn from what was last seen while its picture is blank or hidden, as it briefly is
	// while the net is raised or lowered: long enough to cover that, short enough that a stale one soon goes.
	private static final long ROW_GRACE_MILLIS = 1200;

	private final Client client;
	private final TrawlingPlusPlugin plugin;
	private final TrawlingPlusConfig config;

	@Inject
	TrawlingPlusNetOverlay(Client client, TrawlingPlusPlugin plugin, TrawlingPlusConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		// Each piece of the panel stands on its own; with all three off there is nothing to draw, and
		// neither is there on a boat with no trawling net to mark up.
		boolean anything = plugin.showGuides()
			&& (config.showNetDepths() || config.showNetButton() || config.showNetCorrect());
		Widget rows = anything
			? client.getWidget(InterfaceID.SailingSidepanel.FACILITIES_ROWS)
			: null;
		if (rows == null || rows.isHidden())
		{
			return null;
		}

		// Rows scroll inside a window, so the marks are clipped to it, cutting a part-scrolled row the same way the
		// panel does.
		Widget window = client.getWidget(InterfaceID.SailingSidepanel.FACILITIES_SCROLLABLE);
		Shape clip = graphics.getClip();
		if (window != null && !window.isHidden())
		{
			graphics.clip(window.getBounds());
		}

		// The buttons are only wanted for the guide, and only carry an action while they can be pressed: on anyone's
		// boat, as a captain may let guests set the nets.
		boolean guide = config.showNetButton();
		List<Widget> buttons = guide ? netButtons() : Collections.emptyList();
		long now = System.currentTimeMillis();
		int wanted = plugin.getNearestDepth().netDepth();
		for (NetRow net : netRows(rows, now))
		{
			// The picture of a net is its depth, so a row can never be labelled with another net.
			int depth = net.depth;
			Rectangle picture = net.picture;
			// The two share the picture when both are switched on, and take the middle of it when
			// either has the row to itself.
			boolean withLetter = config.showNetDepths();
			boolean withTick = config.showNetCorrect();
			int middle = picture.y + picture.height / 2;

			if (withLetter)
			{
				int width = pillWidth(graphics, LETTERS[depth]);
				int left = withTick ? picture.x - 3 : picture.x + (picture.width - width) / 2;
				drawPill(graphics, LETTERS[depth], letterColour(depth), left, middle);
			}

			if (wanted < 0)
			{
				// Nothing known to aim at, so no advice either way.
				continue;
			}

			if (depth == wanted)
			{
				if (withTick)
				{
					// Nudged in from the right edge, which sits it evenly against the letter.
					int left = withLetter
						? picture.x + picture.width - TICK_WIDTH - 2
						: picture.x + (picture.width - TICK_WIDTH) / 2;
					drawTick(graphics, left, middle, TICK);
				}
			}
			else if (guide)
			{
				// Lowering a net takes it deeper, so the button to press follows the numbers.
				Rectangle press = guideButton(buttons, net, middle, depth < wanted, now);
				if (press != null)
				{
					highlight(graphics, press);
				}
			}
		}

		graphics.setClip(clip);
		return null;
	}

	/**
	 * The trawling nets on the panel with their depths, top row first, read only off the four depth pictures and drawn
	 * as last seen while a net's picture is anything else.
	 */
	private List<NetRow> netRows(Widget rows, long now)
	{
		List<NetRow> nets = new ArrayList<>();
		// By where each picture is on screen against the rows' own left edge, not its place in whatever holds it,
		// which can sit further right, as the portraits do.
		int left = rows.getBounds().x;
		for (Widget child : children(rows))
		{
			Rectangle bounds = child == null ? null : child.getBounds();
			if (bounds == null || bounds.x - left >= PICTURE_COLUMN)
			{
				continue;
			}

			int sprite = child.getSpriteId();
			boolean net = sprite >= NET_PICTURE_RAISED && sprite <= NET_PICTURE_DEEPEST;
			// Some frames hand back a picture the panel has not laid out yet.
			boolean laidOut = !child.isHidden() && bounds.y >= 0 && bounds.height > 0;
			if (net && laidOut)
			{
				NetRow row = new NetRow(child.getIndex(), sprite - NET_PICTURE_RAISED, bounds, now);
				lastSeen.put(child.getIndex(), row);
				nets.add(row);
			}
			else if (sprite > 0 && !net)
			{
				// The picture of something else entirely, so whatever net was in this place has gone.
				lastSeen.remove(child.getIndex());
			}
			else
			{
				// The depth as last seen, for a moment: drawn where the row is now, which moves as the list scrolls,
				// or where it was while it isn't laid out.
				NetRow seen = lastSeen.get(child.getIndex());
				if (seen != null && now - seen.millis <= ROW_GRACE_MILLIS)
				{
					nets.add(laidOut ? new NetRow(seen.index, seen.depth, bounds, seen.millis) : seen);
				}
			}
		}

		nets.sort((one, other) -> Integer.compare(one.picture.y, other.picture.y));
		return nets;
	}

	/**
	 * Every raise or lower button the panel is currently offering. They only carry an action while someone
	 * is operating that net, so there may be none at all.
	 */
	private List<Widget> netButtons()
	{
		List<Widget> buttons = new ArrayList<>();
		Widget clicks = client.getWidget(InterfaceID.SailingSidepanel.FACILITIES_CONTENT_CLICKLAYER);
		if (clicks == null || clicks.isHidden())
		{
			return buttons;
		}

		for (Widget child : children(clicks))
		{
			if (child != null && !child.isHidden() && buttonKind(child) >= 0)
			{
				buttons.add(child);
			}
		}
		return buttons;
	}

	/**
	 * Where the button that moves a net the given way is, or where it last was if it went missing less
	 * than a game tick ago, or null.
	 */
	private Rectangle guideButton(List<Widget> buttons, NetRow net, int middle, boolean lowering, long now)
	{
		Widget press = buttonOnRow(buttons, middle, lowering);
		if (press != null)
		{
			Rectangle bounds = press.getBounds();
			lastButtons.put(net.index, new SeenButton(bounds, middle, lowering, now));
			return bounds;
		}

		// Moved with its row, which may have scrolled since.
		SeenButton seen = lastButtons.get(net.index);
		if (seen == null || seen.lowering != lowering || now - seen.millis > BUTTON_GRACE_MILLIS)
		{
			return null;
		}
		Rectangle moved = new Rectangle(seen.bounds);
		moved.translate(0, middle - seen.middle);
		return moved;
	}

	private static Widget buttonOnRow(List<Widget> buttons, int middle, boolean lowering)
	{
		for (Widget button : buttons)
		{
			Rectangle bounds = button.getBounds();
			boolean lowers = buttonKind(button) == 0;
			if (lowers == lowering && Math.abs(bounds.y + bounds.height / 2 - middle) <= SAME_ROW)
			{
				return button;
			}
		}
		return null;
	}

	private static Widget[] children(Widget widget)
	{
		Widget[] children = widget.getDynamicChildren();
		if (children == null || children.length == 0)
		{
			children = widget.getChildren();
		}
		return children == null ? new Widget[0] : children;
	}

	/**
	 * 0 for the button that lowers a net, 1 for the one that raises it, and -1 for anything else.
	 */
	private static int buttonKind(Widget widget)
	{
		String[] actions = widget.getActions();
		for (String action : actions == null ? new String[0] : actions)
		{
			if (LOWER.equals(action))
			{
				return 0;
			}
			if (RAISE.equals(action))
			{
				return 1;
			}
		}
		return -1;
	}

	/**
	 * A colour with any transparency taken out. Text is always drawn solid, whatever a saved colour
	 * says, since see-through lettering is only ever harder to read.
	 */
	static Color opaque(Color colour)
	{
		return new Color(colour.getRed(), colour.getGreen(), colour.getBlue());
	}

	private Color letterColour(int depth)
	{
		switch (depth)
		{
			case 1:
				return opaque(config.shallowDepthColour());
			case 2:
				return opaque(config.moderateDepthColour());
			case 3:
				return opaque(config.deepDepthColour());
			default:
				return RAISED_COLOUR;
		}
	}

	/**
	 * A letter on a dark pill, starting at the given edge and centred on the given line.
	 */
	private static void drawPill(Graphics2D graphics, String letter, Color colour, int left, int middle)
	{
		FontMetrics letters = graphics.getFontMetrics();
		int width = letters.stringWidth(letter) + PILL_PADDING * 2;
		int height = letters.getAscent() + PILL_PADDING * 2;
		int top = middle - height / 2;

		graphics.setColor(PILL);
		graphics.fillRoundRect(left, top, width, height, 6, 6);
		graphics.setColor(colour);
		graphics.drawString(letter, left + PILL_PADDING, top + height - PILL_PADDING);
	}

	/**
	 * A tick starting at the given edge and centred on the given line. Shared with the display at the
	 * helm, which ticks the depth once every net is set to it.
	 */
	static void drawTick(Graphics2D graphics, int left, int middle, Color colour)
	{
		graphics.setColor(colour);
		graphics.setStroke(TWO_PIXELS);
		graphics.drawLine(left, middle, left + 3, middle + 4);
		graphics.drawLine(left + 3, middle + 4, left + TICK_WIDTH, middle - 5);
	}

	private static int pillWidth(Graphics2D graphics, String text)
	{
		return graphics.getFontMetrics().stringWidth(text) + PILL_PADDING * 2;
	}

	private static void highlight(Graphics2D graphics, Rectangle button)
	{
		graphics.setColor(new Color(HIGHLIGHT.getRed(), HIGHLIGHT.getGreen(), HIGHLIGHT.getBlue(), 110));
		graphics.fillRoundRect(button.x, button.y, button.width, button.height, 6, 6);
		graphics.setColor(new Color(HIGHLIGHT.getRed(), HIGHLIGHT.getGreen(), HIGHLIGHT.getBlue(), 220));
		graphics.setStroke(TWO_PIXELS);
		graphics.drawRoundRect(button.x, button.y, button.width - 1, button.height - 1, 6, 6);
	}

	/**
	 * A trawling net on the panel: how deep it is set, and where its picture is.
	 */
	private static final class NetRow
	{
		final int index;
		final int depth;
		final Rectangle picture;
		// When the net's picture was last actually seen.
		final long millis;

		NetRow(int index, int depth, Rectangle picture, long millis)
		{
			this.index = index;
			this.depth = depth;
			this.picture = picture;
			this.millis = millis;
		}
	}

	/**
	 * A button highlighted on a net: where it was, which way it moves the net, and when it was last found.
	 */
	private static final class SeenButton
	{
		final Rectangle bounds;
		// The middle of its row's picture when found.
		final int middle;
		final boolean lowering;
		final long millis;

		SeenButton(Rectangle bounds, int middle, boolean lowering, long millis)
		{
			this.bounds = bounds;
			this.middle = middle;
			this.lowering = lowering;
			this.millis = millis;
		}
	}
}

