	@Override
	protected void startUp() throws IOException
	{
		RouteData routeData = ShoalRoute.read(gson);
		routes = ShoalRoute.build(routeData, config.routeSmoothing());
		readShownFish();
		markDanger(routes);
		Set<String> plain = new HashSet<>();
		for (RouteData.Species species : routeData.species)
		{
			if ("any".equals(species.bait))
			{
				plain.add(species.name);
			}
		}
		plainBaitSpecies = plain;
		clientThread.invoke(() ->
		{
			// Not logged in or not aboard, the nets are known to be empty, as logging out and stepping off empty them;
			// aboard part way through a session, what they hold is unknown until they're emptied or opened.
			boolean aboard = client.getGameState() == GameState.LOGGED_IN
				&& client.getVarbitValue(VarbitID.SAILING_PLAYER_IS_ON_PLAYER_BOAT) == 1;
			resetFish(aboard ? -1 : 0);
			inventoryFilled = -1;
			inventoryPlain = -1;
			inventoryFine = -1;
			takePending = false;
			// Started part way through a session, the slots won't change to say what they hold.
			netsFitted = readNetsFitted();
			netsLowered = readNetsLowered();
			// Switched on part way through a session, no login is seen to say whose holds to keep.
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				holds = holdsByAccount.computeIfAbsent(client.getAccountHash(), account -> new HashMap<>());
				boatHold = null;
				// Fishing spots already in sight won't be seen arriving.
				WorldView top = client.getTopLevelWorldView();
				for (NPC npc : top == null ? Collections.<NPC>emptyList() : top.npcs())
				{
					onNpcSpawned(new NpcSpawned(npc));
				}
			}
		});
		hideStopBar = config.showTimerBar();
		hudOnOtherBoats = config.hudOnOtherBoats();
		renderCallbackManager.register(drawCallback);
		overlayManager.add(overlay);
		helmOverlay = new TrawlingPlusHelmOverlay(client, this, overlay);
		overlayManager.add(helmOverlay);
		overlayManager.add(netOverlay);
		overlayManager.add(mapOverlay);
		overlayManager.add(minimapOverlay);
		// Clears the unused key the book's last spread used to be kept under.
		configManager.unsetConfiguration(TrawlingPlusConfig.GROUP, HoldBook.OLD_SPREAD_KEY);
		// Turns Clear around boat on once for everyone, now that it's on by default; it can be turned off again after.
		if (configManager.getConfiguration(TrawlingPlusConfig.GROUP, CLEAR_RESET_KEY) == null)
		{
			configManager.setConfiguration(TrawlingPlusConfig.GROUP, "clearAroundBoat", true);
			configManager.setConfiguration(TrawlingPlusConfig.GROUP, CLEAR_RESET_KEY, true);
		}
		overlayManager.add(holdBook);
		mouseManager.registerMouseListener(holdBook.mouse);
		keyManager.registerKeyListener(holdBook);
		eventBus.register(curiosityTracker);
		eventBus.register(oceanEncounters);
		overlayManager.add(encounterOverlay);
		clientThread.invoke(oceanEncounters::findExisting);
		clientThread.invoke(this::findExistingShoals);
		clientThread.invoke(this::addCatchBoxes);
		log.debug("Trawling Plus started with {} routes, {} points to draw them from", routes.size(),
			routes.stream().mapToInt(ShoalRoute::sampleCount).sum());
	}

	@Override
	protected void shutDown()
	{
		renderCallbackManager.unregister(drawCallback);
		overlayManager.remove(overlay);
		overlayManager.remove(helmOverlay);
		overlayManager.remove(netOverlay);
		overlayManager.remove(mapOverlay);
		overlayManager.remove(minimapOverlay);
		overlayManager.remove(holdBook);
		mouseManager.unregisterMouseListener(holdBook.mouse);
		keyManager.unregisterKeyListener(holdBook);
		eventBus.unregister(curiosityTracker);
		curiosityTracker.reset();
		eventBus.unregister(oceanEncounters);
		overlayManager.remove(encounterOverlay);
		clientThread.invoke(oceanEncounters::reset);
		clientThread.invoke(holdBook::reset);
		worldMapPointManager.removeIf(DangerMarker.class::isInstance);
		worldMapPointManager.removeIf(ShoalMarker.class::isInstance);
		infoBoxManager.removeIf(CatchInfoBox.class::isInstance);
		clientThread.invoke(this::saveLifetime);
		// shutDown runs on the Swing thread; clear on the client thread so it can't race a game tick.
		clientThread.invoke(() ->
		{
			clearShoals();
			// The counts themselves are kept, to put up again on the next start.
			catchBoxes.clear();
			totalBox = null;
			netsBox = null;
			shoalMarkers.clear();
			shoalIconsSeen.clear();
			mapRegionsSeen.clear();
			forecast.clear();
			untrack();
			// Nothing going into or out of the holds is counted while switched off, so what they hold is no longer known.
			holdsByAccount.clear();
			holds = new HashMap<>();
			boatHold = null;
			seaFishing = false;
			fishingSpot = false;
			// Nothing is kept in memory while switched off: the routes and markers are built again on the next start.
			ownBoat = null;
			aboardBoat = null;
			routes = Collections.emptyList();
			plainBaitSpecies = Collections.emptySet();
			dangerMarkers = Collections.emptyList();
			seaSpotPlaces.clear();
			fishedSpot = null;
			spotPaused = false;
			spotPausedAt = null;
			spotHoldChecked = null;
			spotHoldFull = false;
			overlay.forget();
		});
		log.debug("Trawling Plus stopped");
	}

	/**
	 * Whether the game should draw something: everything but the bar over a shoal at a stop while that's to be hidden
	 * and the guides show. The bar is drawn with its ripples' overhead display, so only that is left out.
	 */
	private boolean shouldDraw(Renderable renderable, boolean drawingUI)
	{
		// Someone else's boat only has the display to show the bar on instead while it shows there; without it the
		// game keeps its own.
		return !drawingUI || !hideStopBar || !showGuides || ownBoat == null && !(aboardBoat != null && hudOnOtherBoats)
			|| !(renderable instanceof NPC) || ((NPC) renderable).getId() != NpcID.SAILING_SHOAL_RIPPLES;
	}

