	}

	// A tooltip over each of the game's trawling shoal icons whose route has been recorded, naming its species,
	// and the icons already looked at, so each is matched to a route only once.
	private final List<ShoalMarker> shoalMarkers = new ArrayList<>();
	private final Set<WorldPoint> shoalIconsSeen = new HashSet<>();
	// The map's loaded areas whose icons have been looked through, so each is only looked through once rather than
	// every tick the map is open. Held weakly, so areas the map lets go of aren't kept alive here.
	private final Set<WorldMapRegion> mapRegionsSeen = Collections.newSetFromMap(new WeakHashMap<>());

	/**
	 * An invisible point over one of the game's trawling shoal icons, there for its tooltip.
	 */
	private static final class ShoalMarker extends WorldMapPoint
	{
		// The fish of the route beside the icon, so the tooltip goes with that fish's switch.
		final String fish;

		ShoalMarker(WorldPoint icon, BufferedImage blank, String name, String fish)
		{
			// A tile to the west of the icon's own coordinate, as RuneLite's World Map plugin places its quest icons over
			// the game's: at the coordinate itself a point sits a tile east of the icon it covers.
			super(icon.dx(-1), blank);
			// The padding sits round the icon rather than moving it: the icon's middle goes on the point.
			setImagePoint(new Point(SHOAL_ICON_PAD_LEFT + (blank.getWidth() - SHOAL_ICON_PAD_LEFT - SHOAL_ICON_PAD) / 2,
				blank.getHeight() / 2));
			setTooltip(name);
			this.fish = fish;
		}
	}

	/**
	 * Lays a tooltip naming the species over each trawling shoal icon the world map has loaded beside a recorded route,
	 * once each: only while the map is open, until every recorded route has one, whatever maps routes show on.
	 */
	private void findShoalIcons()
	{
		if (shoalMarkers.size() >= routes.size())
		{
			return;
		}

		Widget map = client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER);
		WorldMap worldMap = map == null || map.isHidden() ? null : client.getWorldMap();
		WorldMapRenderer renderer = worldMap == null ? null : worldMap.getWorldMapRenderer();
		WorldMapRegion[][] regions = renderer == null || !renderer.isLoaded() ? null : renderer.getMapRegions();
		if (regions == null)
		{
			return;
		}

		for (WorldMapRegion[] column : regions)
		{
			for (WorldMapRegion region : column == null ? new WorldMapRegion[0] : column)
			{
				if (region == null || mapRegionsSeen.contains(region))
				{
					continue;
				}

				Collection<WorldMapIcon> icons = region.getMapIcons();
				if (icons == null || icons.isEmpty())
				{
					// Possibly not filled in yet, so looked at again next tick.
					continue;
				}
				mapRegionsSeen.add(region);

				for (WorldMapIcon icon : icons)
				{
					WorldPoint at = icon.getCoordinate();
					if (icon.getType() != TRAWLING_SHOAL_ICON || at == null || !shoalIconsSeen.add(at))
					{
						continue;
					}

					ShoalRoute route = routeBeside(at.getX(), at.getY());
					if (route != null)
					{
						ShoalMarker marker = new ShoalMarker(at, blankLike(icon.getType()), route.getSpecies() + " shoal",
							route.getSpecies());
						shoalMarkers.add(marker);
						if (!hiddenFish.contains(marker.fish))
						{
							worldMapPointManager.add(marker);
						}
					}
				}
			}
		}
	}

	/**
	 * The recorded route a map icon at this place sits beside, or null when none is close enough.
	 */
	private ShoalRoute routeBeside(int x, int y)
	{
		ShoalRoute beside = null;
		// Squared, as every distance below is: they are only compared.
		double closest = SHOAL_ICON_TILES * SHOAL_ICON_TILES;
		for (ShoalRoute route : routes)
		{
			double[][] box = route.corners();
			if (x < box[0][0] - SHOAL_ICON_TILES || x > box[2][0] + SHOAL_ICON_TILES
				|| y < box[0][1] - SHOAL_ICON_TILES || y > box[2][1] + SHOAL_ICON_TILES)
			{
				continue;
			}

			for (int i = 0; i < route.sampleCount(); i++)
			{
				double distance = squared(route.sampleX(i) - x, route.sampleY(i) - y);
				if (distance <= closest)
				{
					closest = distance;
					beside = route;
				}
			}
		}
		return beside;
	}

	/**
	 * A see-through image the size of the game's own icon of this type and a little more all round, so hovering
	 * anywhere over that icon, edges included, shows the tooltip laid over it rather than the game's own label.
	 */
	private BufferedImage blankLike(int type)
	{
		MapElementConfig element = client.getMapElementConfig(type);
		SpritePixels sprite = element == null ? null : element.getMapIcon(false);
		int width = sprite == null ? 15 : Math.max(1, sprite.getWidth());
		int height = sprite == null ? 15 : Math.max(1, sprite.getHeight());
		return new BufferedImage(width + SHOAL_ICON_PAD_LEFT + SHOAL_ICON_PAD, height + SHOAL_ICON_PAD * 2,
			BufferedImage.TYPE_INT_ARGB);
	}

	// Where each route's shoal is in its lap, from when it was last seen, and the route of the shoal last trawled.
	private final ShoalForecast forecast = new ShoalForecast();
	private String trawledRouteName;
	// That route, found again each tick by name, as the routes are built again when the smoothing changes.
	private volatile ShoalRoute trawledRoute;
	// Where the arrow off the boat points, the last trawled shoal's likely place, while it is wanted; and how many ticks
	// in a row that shoal has been in view, the arrow staying a few seconds after it comes back into sight.
	private volatile double[] predictedSpot;
	private int trawledInViewTicks;
	private static final int PREDICTED_ARROW_HOLD_TICKS = 5;
	// The arrow goes once this many ticks (10 minutes) have passed without a catch, so it isn't left pointing long
	// after trawling is done; and the ticks left.
	private static final int PREDICTED_ARROW_TIMEOUT_TICKS = 1000;
	private int predictedArrowTicksLeft;
	// Whether the maps' edge arrows are dismissed until the next catch.
	private boolean edgeArrowDismissed;
	// Entries the plugin put on the open menu, taken off once it closes.
	private final List<MenuEntry> addedMenuEntries = new ArrayList<>();

	/**
	 * Finds once a tick the last trawled shoal's route, which the world map marks until another is trawled, and where
	 * that shoal likely is for the arrow off the boat: while aboard, out of view or just back in it, within 10 minutes
	 * of a catch.
	 */
	private void updatePredictedArrow(boolean aboard)
	{
		if (predictedArrowTicksLeft > 0)
		{
			predictedArrowTicksLeft--;
		}
		ShoalRoute found = null;
		if (trawledRouteName != null)
		{
			for (ShoalRoute route : routes)
			{
				if (route.getName().equals(trawledRouteName))
				{
					found = route;
				}
			}
		}
		trawledRoute = found;
		ShoalRoute trawled = predictedArrowTicksLeft > 0 ? found : null;
		trawledInViewTicks = forecast.inView(trawled) ? trawledInViewTicks + 1 : 0;
		boolean wanted = aboard && config.showPredictedArrow() && trawled != null
			&& !hiddenFish.contains(trawled.getSpecies()) && trawledInViewTicks < PREDICTED_ARROW_HOLD_TICKS;
		double distance = wanted ? forecast.distance(trawled) : -1;
		predictedSpot = distance >= 0 ? trawled.pointAt(distance) : null;
	}

	/**
	 * Notes the route of the shoal being trawled, for the arrow pointing back to it.
	 */
	private void noteTrawled()
	{
		ShoalRoute route = nearestShoal == null ? null : nearestShoal.getRoute();
		if (route != null)
		{
			track(route);
		}
	}

	/**
	 * Follows a shoal's route as the last trawled, as a catch from it does.
	 */
	private void track(ShoalRoute route)
	{
		if (!route.getName().equals(trawledRouteName))
		{
			sayTracking("Now tracking: ", route);
		}
		trawledRouteName = route.getName();
		predictedArrowTicksLeft = PREDICTED_ARROW_TIMEOUT_TICKS;
		edgeArrowDismissed = false;
		// In sight: no arrow until it has been out of sight, rather than for its first few ticks.
		trawledInViewTicks = PREDICTED_ARROW_HOLD_TICKS;
	}

	/**
	 * Forgets the followed shoal from its Untrack entry, saying so in chat.
	 */
	private void stopTracking(ShoalRoute route)
	{
		sayTracking("Stopped tracking: ", route);
		untrack();
	}

	/**
	 * A line in chat about the followed shoal, styled as RuneLite's notification messages but not one.
	 */
	private void sayTracking(String start, ShoalRoute route)
	{
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(new ChatMessageBuilder()
				.append(ChatColorType.HIGHLIGHT)
				.append(start + route.getSpecies() + " at " + route.getName())
				.build())
			.build());
	}

	/**
	 * Forgets the last trawled shoal, its map marks and arrows with it.
	 */
	private void untrack()
	{
		trawledRouteName = null;
		trawledRoute = null;
		edgeArrowDismissed = false;
		predictedSpot = null;
		trawledInViewTicks = 0;
		predictedArrowTicksLeft = 0;
	}

	/**
	 * Whether the maps' edge arrows are hidden: dismissed since the last catch, or timed out like the arrow off
	 * the boat.
	 */
	boolean isEdgeArrowHidden()
	{
		return edgeArrowDismissed || predictedArrowTicksLeft <= 0;
	}

	/**
