	}

	/**
	 * Notifies once per stop when the nearest shoal is about to leave it: as it sets off, or the set number
	 * of seconds before, which can only be known for a stop whose timer is running.
	 */
	private void checkShoalLeaving()
	{
		Shoal shoal = nearestShoal;
		if (shoal == null)
		{
			leavingShoal = null;
			return;
		}

		// Only once it has been seen sitting still: a shoal just come into view reads as stopped until it is
		// seen moving, which would otherwise warn of it leaving a stop it was never at.
		boolean stopped = shoal.seenStopped();
		if (shoal != leavingShoal)
		{
			// A shoal first seen on the move has no stop to warn about until it reaches one.
			leavingShoal = shoal;
			leavingWasStopped = stopped;
			leavingWarned = !stopped;
			return;
		}

		if (stopped && !leavingWasStopped)
		{
			// Arrived at a new stop, which gets a warning of its own.
			leavingWarned = false;
		}

		int seconds = Math.max(0, Math.min(TrawlingPlusConfig.MAX_LEAVING_SECONDS, config.shoalLeavingSeconds()));
		double left = shoal.secondsAtStop();
		boolean due = seconds == 0
			? !stopped && leavingWasStopped
			: stopped && left >= 0 && left <= seconds;
		if (due && !leavingWarned)
		{
			leavingWarned = true;
			notifier.notify(config.notifyShoalLeaving(), seconds == 0
				? (config.plainNotifications() ? "The shoal is leaving its stop." : "The shoal stirs and swims off.")
				: (config.plainNotifications() ? "The shoal leaves its stop in " : "The shoal grows restless. It will move on in ")
					+ seconds + (seconds == 1 ? " second." : " seconds."));
		}
		leavingWasStopped = stopped;
	}

	/**
	 * Notifies as soon as the nearest shoal's animation moves it to another depth, if the nets aren't already set
	 * to it.
	 */
	private void checkDepthChange()
	{
		Shoal shoal = nearestShoal;
		if (shoal == null || !shoal.depthChanged())
		{
			return;
		}

		ShoalDepth depth = shoal.getDepth();
		if (netsFitted && !netsAtDepth && (shoal != depthWarnedShoal || depth != depthWarned))
		{
			depthWarnedShoal = shoal;
			depthWarned = depth;
			notifier.notify(config.notifyDepthChange(), config.plainNotifications()
				? "The shoal depth is now " + depth.toString().toLowerCase() + "." : depthMessage(depth));
		}
	}

	private static String depthMessage(ShoalDepth depth)
	{
		switch (depth)
		{
			case SHALLOW:
				return "The shoal rises into the shallows.";
			case DEEP:
				return "The shoal dives into the deep.";
			default:
				return "The shoal settles at moderate depth.";
		}
	}

	private static String specialShoalMessage(String mixed)
	{
		switch (mixed)
		{
			case "Shimmering":
				return "The shoal begins to shimmer!";
			case "Glistening":
				return "The shoal begins to glisten!";
			default:
				return "The shoal bursts into vibrant colour!";
		}
	}

	/**
	 * Whether every net fitted is already at the depth worth fishing. A boat with no nets, or a shoal
	 * whose depth is not known, has nothing to be right about.
	 */
	private boolean netsSetToDepth()
	{
		int wanted = getNearestDepth().netDepth();
		if (wanted < 0)
		{
			return false;
		}

		boolean fitted = false;
		for (int slot = 0; slot < NET_SLOTS.length; slot++)
		{
			// A slot names the hotspot its net is built on, so an empty slot names no hotspot.
			if (client.getVarbitValue(NET_SLOTS[slot]) <= 0)
			{
				continue;
			}

			fitted = true;
			if (client.getVarbitValue(NET_DEPTHS[slot]) != wanted)
			{
				return false;
			}
		}
		return fitted;
	}

